#!/usr/bin/env python3
"""Industrial water reuse blending solver (PySCIPOpt).

Reads public data from /app/data, solves the linear blending model with SCIP,
and writes /app/submissions/solution.csv with the required schema.
"""

import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUBMIT_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUBMIT_DIR, "solution.csv")

ATTRS = ["tds", "nitrogen", "hardness"]


def read_config():
    with open(os.path.join(DATA_DIR, "config.json"), "r") as f:
        return json.load(f)


def read_sources():
    sources = []
    with open(os.path.join(DATA_DIR, "reuse_sources.csv"), "r") as f:
        reader = csv.DictReader(f)
        for row in reader:
            sources.append(
                {
                    "source_id": row["source_id"].strip(),
                    "available_m3": float(row["available_m3"]),
                    "base_cost_per_m3": float(row["base_cost_per_m3"]),
                    "tds_mg_l": float(row["tds_mg_l"]),
                    "nitrogen_mg_l": float(row["nitrogen_mg_l"]),
                    "hardness_mg_l": float(row["hardness_mg_l"]),
                }
            )
    return sources


def read_users():
    users = []
    with open(os.path.join(DATA_DIR, "water_users.csv"), "r") as f:
        reader = csv.DictReader(f)
        for row in reader:
            users.append(
                {
                    "user_id": row["user_id"].strip(),
                    "demand_m3": float(row["demand_m3"]),
                    "minimum_service_rate": float(row["minimum_service_rate"]),
                    "max_tds_mg_l": float(row["max_tds_mg_l"]),
                    "max_nitrogen_mg_l": float(row["max_nitrogen_mg_l"]),
                    "max_hardness_mg_l": float(row["max_hardness_mg_l"]),
                }
            )
    return users


def read_lanes():
    lanes = []
    with open(os.path.join(DATA_DIR, "source_user_lanes.csv"), "r") as f:
        reader = csv.DictReader(f)
        for row in reader:
            lanes.append(
                {
                    "source_id": row["source_id"].strip(),
                    "user_id": row["user_id"].strip(),
                    "lane_capacity_m3": float(row["lane_capacity_m3"]),
                    "transfer_cost_per_m3": float(row["transfer_cost_per_m3"]),
                }
            )
    return lanes


def round8(v):
    if v is None:
        return 0.0
    v = float(v)
    if abs(v) < 5e-9:
        return 0.0
    return round(v, 8)


def main():
    os.makedirs(SUBMIT_DIR, exist_ok=True)

    config = read_config()
    sources = read_sources()
    users = read_users()
    lanes = read_lanes()

    src_by_id = {s["source_id"]: s for s in sources}
    usr_by_id = {u["user_id"]: u for u in users}

    gap = float(config.get("solver_mip_gap", 0.0005))
    penalty = float(config.get("shortfall_penalty_per_m3", 18.0))
    feas_tol = float(config.get("feasibility_tolerance", 1e-5))

    model = Model("industrial_water_reuse_blending")
    model.setRealParam("limits/gap", gap)

    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None and env_limit.strip() != "":
        try:
            tl = float(env_limit)
            model.setRealParam("limits/time", tl)
        except (TypeError, ValueError):
            pass

    # Flow variables on feasible lanes.
    x = {}
    for lane in lanes:
        s = lane["source_id"]
        u = lane["user_id"]
        cap = lane["lane_capacity_m3"]
        obj = src_by_id[s]["base_cost_per_m3"] + lane["transfer_cost_per_m3"]
        x[(s, u)] = model.addVar(
            name="x_{}_{}".format(s, u), vtype="C", lb=0.0, ub=cap, obj=obj
        )

    # Shortfall variables.
    y = {}
    for usr in users:
        u = usr["user_id"]
        y[u] = model.addVar(
            name="y_{}".format(u), vtype="C", lb=0.0, ub=usr["demand_m3"], obj=penalty
        )

    # Source availability.
    for src in sources:
        s = src["source_id"]
        model.addCons(
            quicksum(x[(s, u)] for (ss, u) in x if ss == s) <= src["available_m3"],
            name="avail_{}".format(s),
        )

    # Demand / shortfall balance and minimum service rate.
    for usr in users:
        u = usr["user_id"]
        inflow = quicksum(x[(s, u)] for (s, uu) in x if uu == u)
        model.addCons(inflow + y[u] == usr["demand_m3"], name="balance_{}".format(u))
        model.addCons(
            inflow >= usr["minimum_service_rate"] * usr["demand_m3"],
            name="minserv_{}".format(u),
        )

    # Blended quality: sum_s (q_sa - Q_ua) x_su <= 0.
    for usr in users:
        u = usr["user_id"]
        limits = {
            "tds": usr["max_tds_mg_l"],
            "nitrogen": usr["max_nitrogen_mg_l"],
            "hardness": usr["max_hardness_mg_l"],
        }
        for a in ATTRS:
            Q = limits[a]
            lhs = quicksum(
                (src_by_id[s][a + "_mg_l"] - Q) * x[(s, u)]
                for (s, uu) in x
                if uu == u
            )
            model.addCons(lhs <= 0.0, name="quality_{}_{}".format(u, a))

    model.setMinimize()
    model.optimize()

    status = model.getStatus()
    if model.getNvars() == 0:
        raise RuntimeError("Model has no variables")

    if not model.getNSols():
        raise RuntimeError("No solution found; status={}".format(status))

    obj_val = model.getObjVal()

    # Extract solution.
    flow_val = {}
    for (s, u), var in x.items():
        flow_val[(s, u)] = model.getVal(var)
    short_val = {u: model.getVal(var) for u, var in y.items()}

    # Validation.
    ok = True
    for src in sources:
        s = src["source_id"]
        out = sum(flow_val[(s, u)] for (ss, u) in flow_val if ss == s)
        if out > src["available_m3"] + feas_tol:
            ok = False
            print("VIOLATION source avail {}: {} > {}".format(s, out, src["available_m3"]))
    for lane in lanes:
        s, u = lane["source_id"], lane["user_id"]
        v = flow_val[(s, u)]
        if v < -feas_tol or v > lane["lane_capacity_m3"] + feas_tol:
            ok = False
            print("VIOLATION lane {}->{}: {}".format(s, u, v))
    for usr in users:
        u = usr["user_id"]
        inflow = sum(flow_val[(s, u)] for (s, uu) in flow_val if uu == u)
        if abs(inflow + short_val[u] - usr["demand_m3"]) > feas_tol:
            ok = False
            print("VIOLATION balance {}: {} + {} != {}".format(u, inflow, short_val[u], usr["demand_m3"]))
        if inflow < usr["minimum_service_rate"] * usr["demand_m3"] - feas_tol:
            ok = False
            print("VIOLATION minserv {}: {} < {}".format(u, inflow, usr["minimum_service_rate"] * usr["demand_m3"]))
        if inflow > feas_tol:
            for a in ATTRS:
                limits = {
                    "tds": usr["max_tds_mg_l"],
                    "nitrogen": usr["max_nitrogen_mg_l"],
                    "hardness": usr["max_hardness_mg_l"],
                }
                blended = sum(
                    src_by_id[s][a + "_mg_l"] * flow_val[(s, u)]
                    for (s, uu) in flow_val
                    if uu == u
                ) / inflow
                if blended > limits[a] + feas_tol:
                    ok = False
                    print("VIOLATION quality {} {}: {} > {}".format(u, a, blended, limits[a]))

    # Write solution.
    with open(SOLUTION_PATH, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["row_type", "source_id", "user_id", "value"])
        for lane in lanes:
            s, u = lane["source_id"], lane["user_id"]
            writer.writerow(["flow", s, u, round8(flow_val[(s, u)])])
        for usr in users:
            u = usr["user_id"]
            writer.writerow(["shortfall", "", u, round8(short_val[u])])

    print("STATUS: {}".format(status))
    print("OBJECTIVE: {}".format(obj_val))
    print("VALIDATION_OK: {}".format(ok))
    print("SOLUTION: {}".format(SOLUTION_PATH))

    if not ok:
        print("WARNING: validation detected violations", file=sys.stderr)


if __name__ == "__main__":
    main()
